const containerRef = ref<HTMLElement | null>(null)
const scenarioMode = ref(false)
const visibleSteps = ref<string[]>([])
const isPlaying = ref(false)
const currentStepIndex = ref(0)
const statusText = ref('')
let isCancelled = false
let animFrameId: number | null = null

// ステップクラスの生成
const stepClassList = computed(() => {
  if (!scenarioMode.value) return []
  return visibleSteps.value.map(s => `show-${s}`)
})

const wait = (ms: number) => new Promise(resolve => setTimeout(resolve, ms))

const getSvg = (): SVGSVGElement | null => {
  return containerRef.value?.querySelector('svg') ?? null
}

// 初期状態に応じた初期可視要素リストの取得
const getInitialVisibleSteps = (): string[] => {
  if (initialState.mode === 'custom') {
    return [...initialState.visibleElements]
  }
  if (initialState.mode === 'all-show') {
    const svg = getSvg()
    if (svg) {
      const elements = svg.querySelectorAll('#body-elements > [id]')
      const ids = Array.from(elements)
        .map(el => el.id)
        .filter(id => id.startsWith('s'))
      if (ids.length > 0) return ids
    }
    return ['all-elements']
  }
  return []
}

// ネイティブ viewBox アニメーション（親 PanZoom があってもなくても自律動作）
const zoomToElement = (
  elementId: string,
  options?: { padding?: number; duration?: number; animate?: boolean }
) => {
  const svg = getSvg()
  if (!svg) return

  const target = svg.querySelector(`#${elementId}`) as SVGGraphicsElement | null
  if (!target) return

  let vb = svg.viewBox.baseVal
  const curVb = { x: vb.x, y: vb.y, w: vb.width, h: vb.height }

  const bbox = target.getBBox()
  const matrix = target.getCTM()
  const svgMatrix = svg.getCTM()

  let finalX = bbox.x
  let finalY = bbox.y
  let finalW = bbox.width
  let finalH = bbox.height

  if (matrix && svgMatrix) {
    const transformMatrix = svgMatrix.inverse().multiply(matrix)
    const pt1 = svg.createSVGPoint()
    pt1.x = bbox.x
    pt1.y = bbox.y
    const p1 = pt1.matrixTransform(transformMatrix)

    const pt2 = svg.createSVGPoint()
    pt2.x = bbox.x + bbox.width
    pt2.y = bbox.y + bbox.height
    const p2 = pt2.matrixTransform(transformMatrix)

    finalX = Math.min(p1.x, p2.x)
    finalY = Math.min(p1.y, p2.y)
    finalW = Math.abs(p2.x - p1.x)
    finalH = Math.abs(p2.y - p1.y)
  }

  // 非表示等でサイズが未取得の場合は安全にスキップ
  if (finalW <= 1 || finalH <= 1) return

  const padRatio = options?.padding ?? 0.15
  const padW = finalW * padRatio
  const padH = finalH * padRatio

  const targetVb = {
    x: finalX - padW,
    y: finalY - padH,
    w: Math.max(1, finalW + padW * 2),
    h: Math.max(1, finalH + padH * 2)
  }

  const duration = options?.animate === false ? 0 : (options?.duration ?? 800)
  if (duration === 0) {
    svg.setAttribute('viewBox', `${targetVb.x} ${targetVb.y} ${targetVb.w} ${targetVb.h}`)
    return
  }

  // アニメーション補間
  if (animFrameId) cancelAnimationFrame(animFrameId)
  const startTime = performance.now()
  const startVb = {
    x: curVb.x,
    y: curVb.y,
    w: Math.max(1, curVb.w),
    h: Math.max(1, curVb.h)
  }

  const easeInOutCubic = (t: number) => {
    return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2
  }

  const stepAnim = (now: number) => {
    const elapsed = now - startTime
    const progress = Math.min(1, elapsed / duration)
    const ease = easeInOutCubic(progress)

    const nx = startVb.x + (targetVb.x - startVb.x) * ease
    const ny = startVb.y + (targetVb.y - startVb.y) * ease
    const nw = Math.max(1, startVb.w + (targetVb.w - startVb.w) * ease)
    const nh = Math.max(1, startVb.h + (targetVb.h - startVb.h) * ease)

    svg.setAttribute('viewBox', `${nx} ${ny} ${nw} ${nh}`)

    if (progress < 1) {
      animFrameId = requestAnimationFrame(stepAnim)
    }
  }

  animFrameId = requestAnimationFrame(stepAnim)
}

// アニメーションクラスの動的適用
const animClassMap: Record<string, string> = {
  'fade-in': 'anim-fade-in',
  'fade-in-slow': 'anim-fade-in-slow',
  'slide-in-left': 'anim-slide-in-left',
  'slide-in-right': 'anim-slide-in-right',
  'slide-in-up': 'anim-slide-in-up',
  'pop-in': 'anim-pop-in',
  'drop-in': 'anim-drop-in',
  'draw-line': 'anim-draw-line',
  'pulse': 'anim-pulse',
  'glow': 'anim-glow',
  'flash': 'anim-flash',
  'bounce': 'anim-bounce',
  'shake': 'anim-shake',
  'spin': 'anim-spin',
  'flow-line': 'anim-flow-line',
  'pulse-loop': 'anim-pulse-loop',
  'fade-out': 'anim-fade-out',
  'slide-out-right': 'anim-slide-out-right',
  'shrink-out': 'anim-shrink-out'
}

const applyElementAnimation = (targetId: string, action: string) => {
  const svg = getSvg()
  if (!svg || !action) return

  let cssClass = animClassMap[action.toLowerCase().trim()]
  if (!cssClass) {
    const raw = action.toLowerCase()
    if (raw.includes('ゆったり') || raw.includes('ゆっくり')) cssClass = 'anim-fade-in-slow'
    else if (raw.includes('フェード')) cssClass = 'anim-fade-in'
    else if (raw.includes('左から')) cssClass = 'anim-slide-in-left'
    else if (raw.includes('右から')) cssClass = 'anim-slide-in-right'
    else if (raw.includes('ポップ') || raw.includes('拡大')) cssClass = 'anim-pop-in'
    else if (raw.includes('回転') || raw.includes('スピン')) cssClass = 'anim-spin'
    else if (raw.includes('破線') || raw.includes('流動')) cssClass = 'anim-flow-line'
    else if (raw.includes('パルス')) cssClass = 'anim-pulse'
  }
  if (!cssClass) return

  const elements = svg.querySelectorAll(`[id="${targetId}"], [id^="${targetId}-"]`)
  elements.forEach(el => {
    const old = Array.from(el.classList).filter(c => c.startsWith('anim-'))
    old.forEach(c => el.classList.remove(c))
    void (el as SVGGraphicsElement).getBoundingClientRect()
    el.classList.add(cssClass!)
  })
}

const clearAllAnimations = () => {
  const svg = getSvg()
  if (!svg) return
  const elements = svg.querySelectorAll('[class*="anim-"]')
  elements.forEach(el => {
    const old = Array.from(el.classList).filter(c => c.startsWith('anim-'))
    old.forEach(c => el.classList.remove(c))
  })
}

// 指定ステップまでの状態を適用
const applyStepState = (targetIndex: number) => {
  if (targetIndex < 0 || targetIndex >= scenarioSteps.length) return
  scenarioMode.value = true
  currentStepIndex.value = targetIndex

  const stepsToApply = scenarioSteps.slice(0, targetIndex + 1)
  const newVisible: string[] = getInitialVisibleSteps()
  let latestFrame = 'f000-all'

  for (const step of stepsToApply) {
    if (step.targetId.startsWith('f')) {
      latestFrame = step.targetId
    } else if (step.targetId.startsWith('s')) {
      if (!newVisible.includes(step.targetId)) {
        newVisible.push(step.targetId)
      }
    }
  }

  visibleSteps.value = newVisible
  const currentStep = scenarioSteps[targetIndex]
  statusText.value = `${currentStep.targetId}: ${currentStep.action}${currentStep.note ? ` (${currentStep.note})` : ''}`

  const pad = latestFrame === 'f000-all' ? 0.05 : 0.15
  zoomToElement(latestFrame, { padding: pad, duration: 600, animate: true })

  if (currentStep.targetId.startsWith('s')) {
    applyElementAnimation(currentStep.targetId, currentStep.action)
  }
}

// シナリオ自動再生
const playScenario = async () => {
  if (isPlaying.value) return
  isPlaying.value = true
  scenarioMode.value = true
  isCancelled = false

  try {
    do {
      visibleSteps.value = getInitialVisibleSteps()
      currentStepIndex.value = 0
      clearAllAnimations()

      for (let i = 0; i < scenarioSteps.length; i++) {
        if (isCancelled) break
        currentStepIndex.value = i
        const step = scenarioSteps[i]

        statusText.value = `${step.targetId} (${step.action})${step.note ? ` — ${step.note}` : ''}`

        if (step.targetId.startsWith('f')) {
          const pad = step.targetId === 'f000-all' ? 0.05 : 0.15
          zoomToElement(step.targetId, {
            padding: pad,
            duration: step.duration > 0 ? Math.min(step.duration, 1000) : 800,
            animate: true
          })
        } else if (step.targetId.startsWith('s')) {
          if (!visibleSteps.value.includes(step.targetId)) {
            visibleSteps.value.push(step.targetId)
          }
          applyElementAnimation(step.targetId, step.action)
        }

        if (step.duration > 0) {
          await wait(step.duration)
        }
      }

      if (isCancelled) break

      statusText.value = '🎉 完了'
      if (props.loop) {
        await wait(2000)
      }
    } while (props.loop && !isCancelled)
  } finally {
    isPlaying.value = false
  }
}

const stopScenario = () => {
  isCancelled = true
  isPlaying.value = false
  statusText.value = '一時停止'
}

const nextStep = () => {
  if (currentStepIndex.value < scenarioSteps.length - 1) {
    applyStepState(currentStepIndex.value + 1)
  }
}

const prevStep = () => {
  if (currentStepIndex.value > 0) {
    applyStepState(currentStepIndex.value - 1)
  }
}

const resetScenario = () => {
  isCancelled = true
  isPlaying.value = false
  scenarioMode.value = false
  visibleSteps.value = []
  currentStepIndex.value = 0
  statusText.value = ''
  clearAllAnimations()

  const svg = getSvg()
  if (svg) {
    zoomToElement('f000-all', { padding: 0.05, duration: 600, animate: true })
  }
}

onMounted(() => {
  if (props.autoPlay) {
    setTimeout(() => {
      playScenario()
    }, 500)
  }
})

onBeforeUnmount(() => {
  isCancelled = true
  if (animFrameId) cancelAnimationFrame(animFrameId)
})

defineExpose({
  play: playScenario,
  stop: stopScenario,
  reset: resetScenario,
  next: nextStep,
  prev: prevStep,
  goToStep: applyStepState
})
</script>

