/* ==========================================================================
   フローチャート固有スタイル（CSSアニメーション ＆ ステップ表示）
   ========================================================================== */
/* ==========================================================================
   SVG フローチャート用共通アニメーション辞書 (Animation Dictionary)
   ========================================================================== */

.flow-svg {
  width: 100%;
  height: auto;
  max-width: 100%;
  max-height: 100%;
  display: block;
}

/* SVG 要素のアニメーション変形基準点を「要素自身の中心」に設定し、トランジション干渉を抑制 */
.anim-target,
[class*="anim-"] {
  transform-box: fill-box;
  transform-origin: center;
  transition: none !important;
}

/* --------------------------------------------------------------------------
   1. 登場系（Enter Animations）
   -------------------------------------------------------------------------- */

/* フェードイン（標準: 0.8s なめらかにふんわり出現） */
.anim-fade-in {
  animation: keyframeFadeIn 0.8s cubic-bezier(0.25, 0.1, 0.25, 1) forwards !important;
}
@keyframes keyframeFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* ゆったりフェードイン（1.8s 余韻を持たせた優しい出現） */
.anim-fade-in-slow {
  animation: keyframeFadeInSlow 1.8s cubic-bezier(0.25, 0.1, 0.25, 1) forwards !important;
}
@keyframes keyframeFadeInSlow {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* 左からスライドイン */
.anim-slide-in-left {
  animation: keyframeSlideInLeft 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
@keyframes keyframeSlideInLeft {
  from {
    opacity: 0;
    transform: translateX(-40px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* 右からスライドイン */
.anim-slide-in-right {
  animation: keyframeSlideInRight 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
@keyframes keyframeSlideInRight {
  from {
    opacity: 0;
    transform: translateX(40px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

/* 下からスライド浮上 */
.anim-slide-in-up {
  animation: keyframeSlideInUp 0.8s cubic-bezier(0.16, 1, 0.3, 1) forwards;
}
@keyframes keyframeSlideInUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ポップイン（弾むように拡大出現） */
.anim-pop-in {
  animation: keyframePopIn 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) forwards;
}
@keyframes keyframePopIn {
  0% {
    opacity: 0;
    transform: scale(0.3);
  }
  70% {
    opacity: 1;
    transform: scale(1.1);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

/* ドロップイン（上から落下して着地） */
.anim-drop-in {
  animation: keyframeDropIn 0.7s cubic-bezier(0.34, 1.3, 0.64, 1) forwards;
}
@keyframes keyframeDropIn {
  0% {
    opacity: 0;
    transform: translateY(-50px);
  }
  70% {
    opacity: 1;
    transform: translateY(4px);
  }
  100% {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ライン描画（スーッと伸びる） */
.anim-draw-line path,
path.anim-draw-line,
.anim-draw-line {
  stroke-dasharray: 1000;
  stroke-dashoffset: 1000;
  animation: keyframeDrawLine 0.9s ease-out forwards;
}
@keyframes keyframeDrawLine {
  from {
    stroke-dashoffset: 1000;
    opacity: 0.2;
  }
  to {
    stroke-dashoffset: 0;
    opacity: 1;
  }
}

/* --------------------------------------------------------------------------
   2. 強調・注目系（Emphasis Animations）
   -------------------------------------------------------------------------- */

/* パルス（ドクンと拍動） */
.anim-pulse {
  animation: keyframePulse 0.8s ease-in-out forwards;
}
@keyframes keyframePulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.12); filter: drop-shadow(0 0 10px rgba(15, 118, 110, 0.6)); }
  100% { transform: scale(1); }
}

/* グロー（神秘的発光） */
.anim-glow {
  animation: keyframeGlow 1s ease-in-out forwards;
}
@keyframes keyframeGlow {
  0% { filter: drop-shadow(0 0 0px rgba(15, 118, 110, 0)); }
  50% { filter: drop-shadow(0 0 16px rgba(15, 118, 110, 0.8)); }
  100% { filter: drop-shadow(0 0 4px rgba(15, 118, 110, 0.3)); }
}

/* フラッシュ（瞬間白光点滅） */
.anim-flash {
  animation: keyframeFlash 0.6s ease-in-out forwards;
}
@keyframes keyframeFlash {
  0%, 100% { opacity: 1; }
  30%, 70% { opacity: 0.2; }
  50% { opacity: 1; filter: brightness(2); }
}

/* バウンス（ピョンと跳ねる） */
.anim-bounce {
  animation: keyframeBounce 0.7s cubic-bezier(0.28, 0.84, 0.42, 1) forwards;
}
@keyframes keyframeBounce {
  0%, 100% { transform: translateY(0); }
  40% { transform: translateY(-18px); }
  60% { transform: translateY(-6px); }
  80% { transform: translateY(-2px); }
}

/* シェイク（小刻みな左右振動） */
.anim-shake {
  animation: keyframeShake 0.6s ease-in-out forwards;
}
@keyframes keyframeShake {
